package su.kidoz.jetaprog.acp.protocol

import kotlinx.serialization.SerializationException
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.JsonPrimitive
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

/** Independent wire fixtures: expected JSON is never generated by the protocol models. */
class AcpWireFormatTest {
    private val json = AcpConnection.defaultJson

    @Test
    fun requestIncludesJsonRpcVersion() {
        val request = AcpRequest(JsonPrimitive(7), "initialize", json.parseToJsonElement("""{"protocolVersion":1}"""))
        assertWireEquals(
            """{"jsonrpc":"2.0","id":7,"method":"initialize","params":{"protocolVersion":1}}""",
            json.encodeToString(request),
        )
    }

    @Test
    fun successAndErrorResponsesIncludeJsonRpcVersionAndPreserveStringIds() {
        assertWireEquals(
            """{"jsonrpc":"2.0","id":"peer-1","result":{}}""",
            json.encodeToString(AcpResponse(JsonPrimitive("peer-1"), result = json.parseToJsonElement("{}"))),
        )
        assertWireEquals(
            """{"jsonrpc":"2.0","id":"peer-2","error":{"code":-32602,"message":"bad params"}}""",
            json.encodeToString(
                AcpResponse(JsonPrimitive("peer-2"), error = AcpError(AcpError.INVALID_PARAMS, "bad params")),
            ),
        )
    }

    @Test
    fun notificationIncludesJsonRpcVersionWithoutAnId() {
        assertWireEquals(
            """{"jsonrpc":"2.0","method":"session/cancel","params":{"sessionId":"s"}}""",
            json.encodeToString(
                AcpNotification("session/cancel", json.parseToJsonElement("""{"sessionId":"s"}""")),
            ),
        )
    }

    @Test
    fun defaultInitializationAlwaysSendsTheProtocolVersion() {
        assertWireEquals("""{"protocolVersion":1}""", json.encodeToString(InitializeRequest()))
        assertWireEquals("""{"protocolVersion":1}""", json.encodeToString(InitializeResponse()))
    }

    @Test
    fun initializationResponseMustDeclareItsVersion() {
        assertFailsWith<SerializationException> { json.decodeFromString<InitializeResponse>("{}") }
    }

    @Test
    fun newAndLoadSessionsIncludeEmptyMcpServerLists() {
        assertWireEquals(
            """{"cwd":"/workspace","mcpServers":[]}""",
            json.encodeToString(NewSessionRequest("/workspace")),
        )
        assertWireEquals(
            """{"sessionId":"s","cwd":"/workspace","mcpServers":[]}""",
            json.encodeToString(LoadSessionRequest("s", "/workspace")),
        )
    }

    private fun assertWireEquals(
        expected: String,
        actual: String,
    ) {
        assertEquals(json.parseToJsonElement(expected), json.parseToJsonElement(actual))
    }
}
